cd /work && python3 - <<'EOF'
import json, subprocess, sys, importlib.util
spec = importlib.util.spec_from_file_location("m", "/work/submission/main.py")
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
L=40; NL=12
nid=L; layers=[]
for _ in range(NL):
    layers.append([nid,nid+1]); nid+=2
dest=nid; n=nid+1
edges=[]
def add(u,v,lab): edges.append({"u":u,"v":v,"ping_us":1,"ack_us":1,"label":lab})
for i in range(L-1): add(i,i+1,"c%d"%(i%10))
for v in layers[0]: add(L-1,v,"L0")
for i in range(NL-1):
    for u in layers[i]:
        for v in layers[i+1]: add(u,v,"M%d"%(i%10))
for u in layers[-1]: add(u,dest,"z")
out=[[] for _ in range(n)]
for i,e in enumerate(edges): out[e["u"]].append(i)
reach=[0]*n; reach[n-1]=1
for u in range(n-2,-1,-1):
    reach[u]=sum(reach[edges[e]["v"]] for e in out[u])
print("reach[0] =", reach[0])
print("n",n,"edges",len(edges))
EOF
